/* @lc app=leetcode id=1765 lang=kotlin */
class Solution { fun highestPeak(isWater: Array<IntArray>): Array<IntArray> = Array(isWater.size) { r -> IntArray(isWater[0].size) { c -> if (isWater[r][c] == 1) 0 else -1 } }.let { ans -> java.util.ArrayDeque<Int>().let { q -> isWater.indices.forEach { r -> isWater[0].indices.forEach { c -> if (isWater[r][c] == 1) q.add(r * 2000 + c) } }.run { while (q.isNotEmpty()) { q.poll().let { curr -> (curr / 2000 to curr % 2000).let { (r, c) -> arrayOf(r-1 to c, r+1 to c, r to c-1, r to c+1).forEach { (nr, nc) -> if (nr in isWater.indices && nc in isWater[0].indices && ans[nr][nc] == -1) run { ans[nr][nc] = ans[r][c] + 1 }.run { q.add(nr * 2000 + nc) } } } } } }.let { ans } } }